use std::{fs,env};
fn main(){let args:Vec<String>=env::args().collect();let request=&args[1];let result=action_printer_core::dispatch(request);let value:serde_json::Value=serde_json::from_str(&result).unwrap();assert!(value["ok"].as_bool().unwrap(),"{result}");let rows=value["rows"].as_u64().unwrap() as usize;let raster=hex::decode(value["raster"].as_str().unwrap()).unwrap();let mut pgm=format!("P5\n96 {rows}\n255\n").into_bytes();for i in 0..rows*96 {pgm.push(if raster[i/8]&(0x80>>(i%8))!=0 {0}else{255});}fs::write(&args[2],pgm).unwrap();println!("{}px font, {} repetitions",value["font_px"],value["repeats"]);}
